@Override public void serialize(ByteBuf b,BedrockCodecHelper h,ClientboundDataStorePacket p){h.writeArray(b,p.getUpdates(),(buf,a)->{VarInts.writeUnsignedInt(buf,a.getType());switch(a.getType()){case 0:DataStoreUpdate u=(DataStoreUpdate)a;h.writeString(buf,u.getDataStoreName());h.writeString(buf,u.getProperty());h.writeString(buf,u.getPath());Object v=u.getData();int t=v instanceof Number?0:v instanceof Boolean?1:v instanceof String?2:-1;VarInts.writeUnsignedInt(buf,t);if(t==0)buf.writeDoubleLE(((Number)v).doubleValue());else if(t==1)buf.writeBoolean((boolean)v);else if(t==2)h.writeString(buf,(String)v);else throw new IllegalStateException("Invalid data store data type "+t);buf.writeIntLE(u.getUpdateCount());buf.writeIntLE(u.getPathUpdateCount());break;case 1:DataStoreChange c=(DataStoreChange)a;h.writeString(buf,c.getDataStoreName());h.writeString(buf,c.getProperty());buf.writeIntLE(c.getUpdateCount());writeDataStoreChange(buf,h,c.getNewValue());break;case 2:h.writeString(buf,((DataStoreRemoval)a).getDataStoreName());break;default:throw new UnsupportedOperationException("Unknown data store action");}});}
